import React, { useState, useEffect } from "react";
import api from "../api";

function Recipes() {
  const [families, setFamilies] = useState([]);
  const [selectedFamily, setSelectedFamily] = useState(null);

  const [selectedDate, setSelectedDate] = useState("");
  const [selectedMealType, setSelectedMealType] = useState("Breakfast");

  const [recipe, setRecipe] = useState("");
  const [mealDescription, setMealDescription] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const MEAL_TYPES = ["Breakfast", "Lunch", "Dinner", "Snacks"];

  useEffect(() => {
    loadFamilies();

    // Set default date to today
    const today = new Date().toISOString().split("T")[0];
    setSelectedDate(today);
  }, []);

  const loadFamilies = async () => {
    try {
      const res = await api.get("/families/");
      setFamilies(res.data);
      if (res.data && res.data.length > 0) {
        setSelectedFamily(res.data[0].id);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const loadRecipe = async () => {
    if (!selectedFamily || !selectedDate || !selectedMealType) return;

    setLoading(true);
    setRecipe("");
    setMealDescription("");
    setError("");

    try {
      const res = await api.get(`/families/${selectedFamily}/recipe`, {
        params: {
          date: selectedDate,
          meal_type: selectedMealType
        }
      });
      setRecipe(res.data.recipe);
      setMealDescription(res.data.meal_description);
    } catch (err) {
      console.error(err);
      if (err.response && err.response.data && err.response.data.detail) {
        setError(err.response.data.detail);
      } else {
        setError("Failed to fetch recipe. Make sure the meal plan is generated for this date and time.");
      }
    }

    setLoading(false);
  };

  return (
    <div className="page anim-fade-in">
      <h1 style={{ color: "#10b981", textShadow: "0 0 10px rgba(16,185,129,0.3)" }}>
        👩‍🍳 AI Recipe Generator
      </h1>
      <p style={{color: "#64748b", marginBottom: "30px"}}>
        Select a date and meal time to generate step-by-step cooking procedures for your generated meals.
      </p>

      <div className="card anim-fade-in" style={{ borderTop: "4px solid #3b82f6", display: "flex", flexWrap: "wrap", gap: "15px", alignItems: "flex-end" }}>

        {families.length > 0 && (
          <div style={{ flex: "1 1 200px" }}>
            <label style={{ display: "block", marginBottom: "8px", color: "#94a3b8" }}>Select Family</label>
            <select
              value={selectedFamily || ""}
              onChange={e => setSelectedFamily(e.target.value)}
              className="date-picker"
              style={{ width: "100%", padding: "10px", borderRadius: "8px" }}
            >
              {families.map(f => (
                <option key={f.id} value={f.id}>{f.name}</option>
              ))}
            </select>
          </div>
        )}

        <div style={{ flex: "1 1 200px" }}>
          <label style={{ display: "block", marginBottom: "8px", color: "#94a3b8" }}>Date</label>
          <input
            type="date"
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
            className="date-picker"
            style={{ width: "100%", padding: "10px", borderRadius: "8px" }}
          />
        </div>

        <div style={{ flex: "1 1 200px" }}>
          <label style={{ display: "block", marginBottom: "8px", color: "#94a3b8" }}>Meal Time</label>
          <select
            value={selectedMealType}
            onChange={(e) => setSelectedMealType(e.target.value)}
            className="date-picker"
            style={{ width: "100%", padding: "10px", borderRadius: "8px" }}
          >
            {MEAL_TYPES.map(m => (
              <option key={m} value={m}>{m}</option>
            ))}
          </select>
        </div>

        <div style={{ flex: "1 1 200px" }}>
          <button 
            onClick={loadRecipe} 
            disabled={loading}
            style={{ 
              width: "100%", 
              background: loading ? "#64748b" : "#3b82f6", 
              padding: "12px",
              marginTop: "auto"
            }}
          >
            {loading ? "Generating..." : "Generate AI Recipe"}
          </button>
        </div>
      </div>

      {error && (
        <div style={{ marginTop: "20px", padding: "15px", background: "rgba(239, 68, 68, 0.1)", borderLeft: "4px solid #ef4444", color: "#ef4444", borderRadius: "4px" }}>
          {error}
        </div>
      )}

      {recipe && (
        <div style={{ marginTop: "30px", display: "flex", flexWrap: "wrap", gap: "20px" }}>

          {mealDescription && (
            <div className="card anim-fade-in" style={{ flex: "1 1 300px", borderTop: "4px solid #f59e0b" }}>
              <h2 style={{ color: "#f59e0b", margin: "0 0 15px 0" }}>📸 AI Meal Visualization</h2>
              <div style={{ overflow: "hidden", borderRadius: "10px", boxShadow: "0 4px 10px rgba(0,0,0,0.3)" }}>
                <img 
                  src={`https://image.pollinations.ai/prompt/${encodeURIComponent(`Delicious, professional food photography of ${mealDescription}, photorealistic, dramatic lighting, highly detailed`)}?width=800&height=600&nologo=true`} 
                  alt={mealDescription}
                  style={{ width: "100%", height: "auto", display: "block" }} 
                />
              </div>
            </div>
          )}

          <div className="card anim-fade-in" style={{ flex: "2 1 500px", borderTop: "4px solid #10b981" }}>
            <h2 style={{ color: "#10b981", margin: "0 0 15px 0" }}>🍲 Cooking Procedure</h2>
            <div className="pre" style={{ background: "#0f172a", padding: "20px", borderRadius: "8px", color: "#e2e8f0", whiteSpace: "pre-wrap", lineHeight: "1.6" }}>
              {recipe}
            </div>
          </div>

        </div>
      )}
    </div>
  );
}

export default Recipes;
